use tower_http::services::ServeDir;

const MAX_WEBSOCKET_MESSAGE_BYTES: usize = 16 * 1024 * 1024;

#[derive(Clone)]
pub struct AppState(pub Arc<AppInner>);
pub struct AppInner {
    pub switchboard: Mutex<Switchboard>,
    pub transcript_log: Mutex<TranscriptLog>,
    pub speaker: Speaker,
    pub stt: SttAdapter,
    pub events: broadcast::Sender<Event>,
    status_snapshot: Arc<StdRwLock<Value>>,
    speech: mpsc::Sender<SpeechRequest>,
    speech_rx: Mutex<Option<mpsc::Receiver<SpeechRequest>>>,
    clips: mpsc::Sender<Clip>,
    clip_rx: Mutex<Option<mpsc::Receiver<Clip>>>,
    pub turns: mpsc::Sender<(String, String, u64)>,
    turn_rx: Mutex<Option<mpsc::Receiver<(String, String, u64)>>>,
    pub accepted_clips: Mutex<(HashSet<String>, VecDeque<String>)>,
    pub last_diagram: Arc<Mutex<Option<Value>>>,
    pub active_session: Arc<Mutex<Option<PiSession>>>,
    activity_clock: ActivityClock,
    live_leg: LiveLegState,
    operation_transition: Mutex<()>,
    active_operations: Mutex<HashMap<TaskId, AbortHandle>>,
    pub turn_generation: AtomicU64,
    pub queued_turns: AtomicU64,
    pub turn_in_flight: AtomicBool,
    shutdown: watch::Sender<bool>,
    audio: Mutex<AudioQueue>,
}
#[derive(Clone, Debug)]
pub enum Event {
    Json(Value),
    Audio {
        audio: Vec<u8>,
        generation: u64,
        sequence: u64,
    },
}
struct SpeechRequest {
    text: String,
    generation: u64,
    sequence: u64,
}
struct AudioSlot {
    generation: u64,
    audio: Option<Vec<u8>>,
}
struct AudioQueue {
    next: u64,
    emit: u64,
    slots: BTreeMap<u64, AudioSlot>,
}
impl AudioQueue {
    fn new() -> Self {
        Self {
            next: 0,
            emit: 0,
            slots: BTreeMap::new(),
        }
    }
    fn reserve(&mut self, generation: u64) -> u64 {
        let sequence = self.next;
        self.next += 1;
        self.slots.insert(
            sequence,
            AudioSlot {
                generation,
                audio: None,
            },
        );
        sequence
    }
    fn finish(&mut self, sequence: u64, generation: u64, audio: Vec<u8>) -> Vec<Event> {
        let Some(slot) = self.slots.get_mut(&sequence) else {
            return Vec::new();
        };
        if slot.generation == generation {
            slot.audio = Some(audio);
        } else {
            slot.audio = Some(Vec::new());
        }
        let mut ready = Vec::new();
        while let Some(slot) = self.slots.get(&self.emit) {
            if slot.audio.is_none() {
                break;
            }
            let slot = self.slots.remove(&self.emit).expect("audio slot exists");
            if let Some(audio) = slot.audio {
                if !audio.is_empty() {
                    ready.push(Event::Audio {
                        audio,
                        generation: slot.generation,
                        sequence: self.emit,
                    });
                }
            }
            self.emit += 1;
        }
        ready
    }
    fn clear(&mut self) {
        self.slots.clear();
        self.emit = self.next;
    }
}

